(function(root){
 'use strict';const OXFORD='shorter-oxford-psychiatry-8-ru',FISH='fish-clinical-psychopathology-5-ru',PRACTICE='psycholibrary:practice:v1',HUB='psycholibrary:hub:v1',QUIZ='psycholibrary:knowledge:v1',JOURNAL='psycholibrary:restore-journal:v1',KEYS=[OXFORD+':state:v1',FISH+':state:v1',QUIZ,PRACTICE,HUB];
 const clone=x=>JSON.parse(JSON.stringify(x)),id=x=>typeof x==='string'&&/^[a-z0-9][a-z0-9-]{0,100}$/.test(x),assert=(ok,msg)=>{if(!ok)throw Error(msg);};
 function bounded(value,depth=0){assert(depth<9,'Слишком сложная структура');if(value===null||typeof value==='boolean')return;if(typeof value==='number'){assert(Number.isFinite(value),'Некорректное число');return;}if(typeof value==='string'){assert(value.length<=20000,'Слишком длинная запись');return;}assert(value&&typeof value==='object','Некорректная запись');const entries=Object.entries(value);assert(entries.length<=500,'Слишком много элементов');for(const [k,v]of entries){assert(!['__proto__','constructor','prototype'].includes(k),'Недопустимый ключ');bounded(v,depth+1);}}
 function cleanPractice(raw){assert(raw&&raw.schemaVersion===1&&raw.cases&&raw.drafts&&raw.completed,'Неверная копия практики');assert(JSON.stringify(raw).length<=2000000,'Копия практики слишком велика');bounded(raw);for(const field of ['cases','drafts','completed'])assert(typeof raw[field]==='object'&&!Array.isArray(raw[field]),'Повреждённый раздел практики');for(const [k,v]of Object.entries(raw.drafts))assert(id(k)&&typeof v==='string'&&v.length<=10000,'Повреждённый черновик');for(const [k,v]of Object.entries(raw.completed))assert(id(k)&&Number.isFinite(v)&&v>=0,'Повреждена отметка практики');for(const [k,v]of Object.entries(raw.cases)){assert(id(k)&&v&&typeof v==='object'&&!Array.isArray(v),'Повреждён сценарий');for(const f of ['initial','final','why'])if(v[f]!==undefined)assert(typeof v[f]==='string'&&v[f].length<=10000,'Повреждён ответ сценария');for(const f of ['revealed','next'])if(v[f]!==undefined)assert(Array.isArray(v[f])&&v[f].length<=100&&v[f].every(x=>typeof x==='string'&&x.length<=100),'Повреждён выбор сценария');if(v.feedback!==undefined)assert(typeof v.feedback==='boolean','Повреждён разбор сценария');}return clone(raw);}
 const emptyPractice=()=>({schemaVersion:1,cases:{},drafts:{},completed:{}});
 function cleanReader(raw,bookId){assert(raw&&raw.schemaVersion===1&&raw.bookId===bookId,'Копия относится к другому учебнику');const s={schemaVersion:1,bookId,notes:{},completed:{},positions:{},lastSection:null,rate:1,voice:'',fontSize:20};for(const field of ['notes','completed','positions'])assert(raw[field]&&typeof raw[field]==='object'&&!Array.isArray(raw[field]),'Повреждённые данные учебника');for(const [k,v]of Object.entries(raw.notes)){assert(id(k)&&typeof v==='string'&&v.length<=1000000,'Повреждённая заметка');s.notes[k]=v;}for(const [k,v]of Object.entries(raw.completed)){assert(id(k)&&v&&Number.isInteger(v.revision)&&/^[a-f0-9]{64}$/.test(v.source),'Повреждена отметка чтения');s.completed[k]={revision:v.revision,source:v.source};}for(const [k,v]of Object.entries(raw.positions)){assert(id(k)&&Number.isFinite(v)&&v>=0,'Повреждено место чтения');s.positions[k]=v;}assert(raw.lastSection===null||id(raw.lastSection),'Повреждён последний раздел');s.lastSection=raw.lastSection;s.rate=[.75,1,1.25,1.5].includes(raw.rate)?raw.rate:1;s.voice=typeof raw.voice==='string'?raw.voice.slice(0,500):'';s.fontSize=[18,20,22,24].includes(raw.fontSize)?raw.fontSize:20;return s;}
 function cleanEntry(key,raw,bank){if(key===OXFORD+':state:v1')return cleanReader(raw,OXFORD);if(key===FISH+':state:v1')return cleanReader(raw,FISH);if(key===QUIZ)return KnowledgeModel.restoreState(raw,bank);if(key===PRACTICE)return cleanPractice(raw);if(key===HUB){bounded(raw);return clone(raw);}throw Error('Неизвестный раздел копии');}
 function backup(storage,bank){const entries={};for(const k of KEYS){const raw=storage.getItem(k);if(raw!==null)entries[k]=cleanEntry(k,JSON.parse(raw),bank);}return{format:'psycholibrary-unified-backup',schemaVersion:1,exportedAt:new Date().toISOString(),entries};}
 function importBackup(raw,bank){let entries;if(raw?.format==='psycholibrary-knowledge-backup')entries={[QUIZ]:KnowledgeModel.importBackup(raw,bank)};else if(raw?.format==='psycholibrary-practice-backup'&&raw.schemaVersion===1)entries={[PRACTICE]:raw.state};else if(raw?.schemaVersion===1&&[OXFORD,FISH].includes(raw.bookId))entries={[raw.bookId+':state:v1']:raw};else{assert(raw?.format==='psycholibrary-unified-backup'&&raw.schemaVersion===1&&raw.entries&&typeof raw.entries==='object'&&!Array.isArray(raw.entries),'Это не резервная копия библиотеки');entries=raw.entries;}const cleaned={};assert(Object.keys(entries).length>0&&Object.keys(entries).length<=KEYS.length,'Пустая или неверная копия');for(const [k,v]of Object.entries(entries))cleaned[k]=cleanEntry(k,v,bank);return cleaned;}
 function rollback(storage,old){for(const k of Object.keys(old))storage.removeItem(k);for(const [k,v]of Object.entries(old))if(v!==null)storage.setItem(k,v);storage.removeItem(JOURNAL);}
 function recoverRestore(storage){const raw=storage.getItem(JOURNAL);if(!raw)return false;const old=JSON.parse(raw);assert(Object.keys(old).every(k=>KEYS.includes(k))&&Object.values(old).every(v=>v===null||typeof v==='string'),'Повреждён журнал восстановления');rollback(storage,old);return true;}
 function restore(storage,entries){const old=Object.fromEntries(Object.keys(entries).map(k=>[k,storage.getItem(k)]));storage.setItem(JOURNAL,JSON.stringify(old));try{for(const [k,v]of Object.entries(entries))storage.setItem(k,JSON.stringify(v));storage.removeItem(JOURNAL);}catch(e){try{rollback(storage,old);}catch{throw Error('Восстановление прервано. Исходные записи сохранены в журнале; повторите открытие центра после устранения ошибки хранилища.');}throw Error('Восстановление отменено: исходные данные возвращены. '+e.message);}return true;}
 function highlightParts(text,query){const a=String(text),q=String(query||'').trim();if(!q)return[{text:a,match:false}];const fold=s=>s.toLocaleLowerCase('ru').replaceAll('ё','е'),at=fold(a).indexOf(fold(q));if(at<0)return[{text:a,match:false}];return[{text:a.slice(0,at),match:false},{text:a.slice(at,at+q.length),match:true},{text:a.slice(at+q.length),match:false}];}
 root.PlatformModel={OXFORD,FISH,PRACTICE,HUB,QUIZ,JOURNAL,KEYS,emptyPractice,cleanPractice,cleanReader,backup,importBackup,restore,recoverRestore,highlightParts};if(typeof module!=='undefined')module.exports=root.PlatformModel;
})(globalThis);
